  slug TEXT NOT NULL UNIQUE,
  public_question TEXT NOT NULL,
  what_counts TEXT,
  metadata_line TEXT,
  homepage_eligible INTEGER NOT NULL DEFAULT 0,
  share_preview TEXT,
  active INTEGER NOT NULL DEFAULT 1,
